import{_ as t,o as a,c as o,a8 as s}from"./chunks/framework.BppdKxCY.js";const u=JSON.parse('{"title":"EP.20 SSE 流式传输","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.20-sse-streaming.md","filePath":"comics/EP.20-sse-streaming.md","lastUpdated":1793421673000}'),i={name:"comics/EP.20-sse-streaming.md"};function r(n,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="ep-20-sse-流式传输" tabindex="-1">EP.20 SSE 流式传输 <a class="header-anchor" href="#ep-20-sse-流式传输" aria-label="Permalink to &quot;EP.20 SSE 流式传输&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../21-frontend-ai-interview">21-frontend-ai-interview.md</a>（21.1 SSE 流技术：AI 流式响应的地基）· 示例：<code>examples/14-01-sse-parser.ts</code>、<code>examples/06-03-sse.ts</code>、<code>examples/14-02-stream-chat.tsx</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君上线 AI 问答，用户盯着转圈十秒，整段答案才&quot;砰&quot;地出现，差评如潮。</li><li><strong>第 2 格</strong>：码叔揭秘 SSE——一个不关的 HTTP 长响应，<code>Content-Type: text/event-stream</code>，<code>data:</code> 行 + <strong>空行分帧</strong>，服务端持续推、浏览器逐帧收。</li><li><strong>第 3 格</strong>：像素酱实证两种接法：GET 简单通知用原生 <a href="https://developer.mozilla.org/zh-CN/docs/Web/API/EventSource" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>EventSource</code></a>（自带重连 + Last-Event-ID）；LLM 要 POST 和鉴权头，用 <code>fetch</code> + ReadableStream 手写解析。</li><li><strong>第 4 格</strong>：码叔结案——chunk 必须缓冲切帧、代理缓冲会把流变便秘、AbortController 给停止键。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-整包等待为什么难熬" tabindex="-1">第 1 格 · 整包等待为什么难熬 <a class="header-anchor" href="#第-1-格-·-整包等待为什么难熬" aria-label="Permalink to &quot;第 1 格 · 整包等待为什么难熬&quot;">​</a></h3><ul><li>大模型是一个 token 一个 token 生成的，非流式接口却要等全部生成完才返回；</li><li>用户承受 TTFT（首字延迟）+ 总时长的<strong>双重等待</strong>，中间零反馈；</li><li>流式把&quot;思考过程&quot;变成可见内容，感知速度远快于实际速度。</li></ul><h3 id="第-2-格-·-sse-协议四件套" tabindex="-1">第 2 格 · SSE 协议四件套 <a class="header-anchor" href="#第-2-格-·-sse-协议四件套" aria-label="Permalink to &quot;第 2 格 · SSE 协议四件套&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> text/event-stream</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">retry</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 101</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {&quot;delta&quot;:&quot;你好&quot;}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> [DONE]</span></span></code></pre></div><ul><li><code>data:</code> 数据行（可多行，分发时用 <code>\\n</code> 拼接）；<code>event:</code> 类型；<code>id:</code> 断点编号；<code>retry:</code> 重连间隔；冒号开头是心跳注释；</li><li><strong>空行（<code>\\n\\n</code>）= 一帧结束</strong>，浏览器只在此时分发事件；</li><li>本质是&quot;一个 HTTP 请求 + 一条持续增长的响应体&quot;，服务端 → 客户端<strong>单向</strong>。</li></ul><h3 id="第-3-格-·-eventsource-与-fetch-两条路" tabindex="-1">第 3 格 · EventSource 与 fetch 两条路 <a class="header-anchor" href="#第-3-格-·-eventsource-与-fetch-两条路" aria-label="Permalink to &quot;第 3 格 · EventSource 与 fetch 两条路&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>EventSource</th><th>fetch + ReadableStream</th></tr></thead><tbody><tr><td>方法</td><td>只能 GET</td><td>任意（LLM 用 POST）</td></tr><tr><td>请求头</td><td>不能自定义</td><td>Authorization 随便带</td></tr><tr><td>重连</td><td>内置 + Last-Event-ID 续传</td><td>自己实现</td></tr><tr><td>适用</td><td>通知、行情</td><td><strong>AI 流式对话</strong></td></tr></tbody></table><ul><li>网络 chunk 边界 ≠ 协议帧边界：<code>TextDecoder.decode(v, { stream: true })</code> 防半个汉字乱码，字符串缓冲按 <code>\\n\\n</code> 切帧、残帧留下次；</li><li>代码芯片里的两级缓冲是本话最重要的考点。</li></ul><h3 id="第-4-格-·-生产环境三个坑" tabindex="-1">第 4 格 · 生产环境三个坑 <a class="header-anchor" href="#第-4-格-·-生产环境三个坑" aria-label="Permalink to &quot;第 4 格 · 生产环境三个坑&quot;">​</a></h3><ul><li><strong>代理缓冲</strong>：Nginx 默认 <code>proxy_buffering on</code> + gzip 会攒批转发，流变整段蹦；要 <code>proxy_buffering off</code> 或响应头 <code>X-Accel-Buffering: no</code>；</li><li><strong>中止</strong>：<code>controller.abort()</code> 关闭连接实现&quot;停止生成&quot;，服务端探测到断连应取消模型调用省钱；</li><li><strong>续传</strong>：<code>id:</code> + <code>Last-Event-ID</code>，服务端从断点补发，客户端幂等去重。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../21-frontend-ai-interview#_21-7-3-常见误区总清单">《21.7.3 常见误区总清单》</a></p></blockquote><ol><li>收到 chunk 就渲染：半个 JSON 解析失败、半个汉字乱码——必须两级缓冲按空行切帧；</li><li>上线后&quot;假流式&quot;：90% 是 Nginx/CDN/压缩中间件在缓冲，用 <code>curl -N</code> 逐段排查；</li><li>EventSource 硬塞 POST 场景：方向错了，应换 fetch 读流；</li><li>不处理 AbortError：用户主动停止被当成错误弹提示、还自动重连。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li><strong>SSE 一帧如何界定？为什么需要缓冲区？</strong>——空行（双换行）结束一帧；TCP chunk 会把一帧切成多段，必须拼到完整帧再解析；字节层还要 <a href="https://developer.mozilla.org/zh-CN/docs/Web/API/TextDecoder" target="_blank" rel="noopener noreferrer" title="MDN 文档"><code>TextDecoder</code></a> 的 <code>stream:true</code> 防多字节截断。</li><li><strong>LLM 流式接口为什么用 fetch 而不是 EventSource？</strong>——EventSource 只支持 GET、不能自定义鉴权头、不能携带大请求体；fetch 可 POST、带 Authorization、用 AbortController 中止，且响应体同样按 SSE 格式解析。</li><li><strong>AI 回答一卡一卡整段出现，怎么排查？</strong>——分层定位：<code>curl -N</code> 直连服务端口 → 应用压缩/缓冲中间件 → Nginx proxy_buffering/gzip → CDN → 客户端是否按帧消费；辅以 TTFT/首帧时间监控。</li></ol>`,20)])])}const k=t(i,[["render",r]]);export{u as __pageData,k as default};
